<script setup>
import {isStaticHosting,sitePath} from '../paths.js';

import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {Blocks,LayoutTemplate,Layers,Image,FolderOpen,History,Plus,Search,ChevronRight,ChevronDown,ArrowUpRight,ArrowLeft,Check,CheckCheck,Eye,EyeOff,Play,Pause,Undo2,Redo2,MousePointer2,Hand,Grid2X2,Magnet,Group,Ungroup,AlignLeft,AlignCenter,AlignRight,AlignStartVertical,AlignEndVertical,AlignVerticalJustifyCenter,ArrowUpToLine,ArrowDownToLine,Copy,Trash2,Lock,Unlock,Download,Upload,Code2,Share2,Settings2,Keyboard,X,Maximize2,MoveHorizontal,MoveVertical,HelpCircle,ExternalLink,Globe2,ShieldCheck,Link2,Box,Video,Shapes,PanelTop,Database,MoreHorizontal,CheckCircle2,CloudUpload,Save,LoaderCircle,FileJson,Monitor,FolderPlus,LogIn,Cloud} from 'lucide-vue-next';
import {useWorkbench} from './useWorkbench.js';import {catalog,chartTypes,themeById} from './catalog.js';import {templates} from './templates.js';import {importPackage} from './package.js';
import {validateProject,projectForExport} from './schema.js';import {storeAll,storeGet} from './storage.js';import {downloadBlob,makeZip} from '../studio/export.js';import CanvasEditor from './components/CanvasEditor.vue';import PropertyPanel from './components/PropertyPanel.vue';import MiniPreview from './components/MiniPreview.vue';import TemplatePreview from './components/TemplatePreview.vue';import ScreenPlayer from './components/ScreenPlayer.vue';import './workbench.css';import './runtime/screen.css';
const w=useWorkbench();const {project,selectedIds,selection,selected,ready,playing,assetUrls,libraryAssets,projects,snapshots,saveStatus,toast,canUndo,canRedo}=w;
const nav=ref(new URLSearchParams(location.search).get('panel')==='templates'?'templates':'components'),category=ref('全部'),query=ref(''),editor=ref(),fileInput=ref(),jsonInput=ref(),modal=ref(null),showAlign=ref(false),showMore=ref(false),session=ref(null),cloudVersions=ref([]),cloudProjects=ref([]),busy=ref(false),publishMode=ref('public'),password=ref(''),shareUrl=ref(''),publishError=ref(''),inspectorOpen=ref(window.innerWidth>980),shortHelp=ref(false);let clipboard=null,lastFocus=null;const libraryUrls=new Map();
const navItems=[{id:'components',name:'组件',icon:Blocks},{id:'templates',name:'模板',icon:LayoutTemplate},{id:'layers',name:'图层',icon:Layers},{id:'assets',name:'素材',icon:Image},{id:'projects',name:'项目',icon:FolderOpen},{id:'history',name:'历史',icon:History}];
const filtered=computed(()=>catalog.filter(c=>(category.value==='全部'||c.category===category.value)&&(c.name+c.description).includes(query.value)));const currentTemplate=computed(()=>templates.find(t=>t.id===project.value.templateId));
const currentTheme=computed(()=>themeById(project.value.theme));const objectCount=computed(()=>project.value.nodes.length);const libraryCount=computed(()=>catalog.length);const cloudReady=computed(()=>!!session.value?.user);
async function loadSession(){if(isStaticHosting)return;try{const r=await fetch('/api/session');if(r.ok)session.value=await r.json();}catch{}}
async function openCloudProject(id){try{const response=await fetch('/api/projects/'+id);const value=await response.json();if(!response.ok)throw Error(value.error);await w.setProject(value.project);}catch(e){w.notify(e.message);}}
async function openNav(id){nav.value=id;query.value='';if(id==='projects'){await w.save();projects.value=(await storeAll('projects')).sort((a,b)=>b.updatedAt-a.updatedAt);if(cloudReady.value)try{const r=await fetch('/api/projects');if(r.ok)cloudProjects.value=await r.json();}catch{}}if(id==='history'&&cloudReady.value)try{const r=await fetch('/api/versions?projectId='+project.value.id);if(r.ok)cloudVersions.value=await r.json();}catch{}}
function add(type,position){return w.add(type,position);}
function dragComponent(e,item){e.dataTransfer.setData('astra/component',item.type);e.dataTransfer.effectAllowed='copy';}
function toggleVisible(n){n.visible=!n.visible;w.record();}function toggleLock(n){n.locked=!n.locked;if(n.locked)selectedIds.value=selectedIds.value.filter(id=>id!==n.id);w.record();}
function assetUrl(a){if(assetUrls.value[a.id])return assetUrls.value[a.id];if(!libraryUrls.has(a.id)&&a.blob)libraryUrls.set(a.id,URL.createObjectURL(a.blob));return libraryUrls.get(a.id)||a.url||'';}
async function files(e){const files=[...e.target.files];e.target.value='';if(!files.length)return;busy.value=true;try{await w.addAssets(files);}catch(e){w.notify(e.message);}finally{busy.value=false;}}
async function importConfig(e){const f=e.target.files?.[0];e.target.value='';if(!f)return;try{if(f.name.endsWith('.zip')){await w.setProject(await importPackage(f));libraryAssets.value=await storeAll('assets');}else{if(f.size>8*1024*1024)throw Error('配置文件最大 8 MB');await w.setProject(validateProject(JSON.parse(await f.text())));}w.notify('项目已恢复，可继续设计');}catch(e){w.notify(e.message);}}
function exportConfig(){const p=projectForExport(w.raw());downloadBlob(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}),p.name+'.astra.json');showMore.value=false;w.notify('项目配置已导出');}
async function exportPackage(){busy.value=true;try{const p=projectForExport(w.raw()),entries=[{name:'screen.astra.json',content:JSON.stringify(p,null,2)},{name:'README.md',content:'# Astra 大屏项目\n\n在 Astra Studio 中导入 screen.astra.json。也可以直接导入整个 .astra.zip 项目包，素材会自动恢复。\n\n预览入口：'+location.origin+sitePath('/')+'\n\n该包包含可编辑布局、样式、数据源和交互配置；HTTP/SQL/WebSocket 仍需要相应数据服务。私有请求头未导出。\n'}];for(const a of p.assets){const stored=await storeGet('assets',a.id);if(stored?.blob)entries.push({name:'assets/'+a.id+'-'+a.name.replace(/[^\w.\u4e00-\u9fff-]/g,'_'),content:new Uint8Array(await stored.blob.arrayBuffer())});}downloadBlob(makeZip(entries),p.name+'.astra.zip');w.notify('可编辑项目与素材已打包');}catch(e){w.notify(e.message);}finally{busy.value=false;showMore.value=false;}}
async function localSnapshot(){await w.snapshot();}
async function cloudSnapshot(){if(!cloudReady.value){modal.value='publish';return;}busy.value=true;try{const response=await fetch('/api/versions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:w.raw(),name:'云端快照 '+new Date().toLocaleString('zh-CN')})});const result=await response.json();if(!response.ok)throw Error(result.error);cloudVersions.value.unshift(result);w.notify('云端快照已保存');}catch(e){w.notify(e.message);}finally{busy.value=false;}}
async function restoreCloud(s){try{const r=await fetch('/api/versions/'+s.id);const result=await r.json();if(!r.ok)throw Error(result.error);await w.restoreSnapshot({project:result.project});}catch(e){w.notify(e.message);}}
async function publish(){publishError.value='';if(!cloudReady.value){publishError.value='请先登录，发布记录与素材会保存在你的账号下。';return;}if(publishMode.value==='password'&&password.value.length<6){publishError.value='查看密码至少 6 位';return;}busy.value=true;try{await w.save();for(const asset of project.value.assets){if(asset.cloud)continue;const local=await storeGet('assets',asset.id);if(local?.blob){const form=new FormData();form.set('file',local.blob,asset.name);form.set('id',asset.id);form.set('projectId',project.value.id);const r=await fetch('/api/assets',{method:'POST',body:form});const result=await r.json();if(!r.ok)throw Error(result.error);asset.cloud=true;asset.url=result.url;}}
 const response=await fetch('/api/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:w.raw(),mode:publishMode.value,password:publishMode.value==='password'?password.value:undefined})});const result=await response.json();if(!response.ok)throw Error(result.error);shareUrl.value=result.url;password.value='';w.notify('大屏已发布，历史版本已自动保存');}catch(e){publishError.value=e.message||'发布失败，请重试';}finally{busy.value=false;}}
async function copyShare(){try{await navigator.clipboard.writeText(shareUrl.value);w.notify('分享链接已复制');}catch{w.notify('请选中链接复制');}}
function keydown(e){if(e.key==='Escape'){modal.value=null;showAlign.value=false;showMore.value=false;return;}if(modal.value){if(e.key==='Tab'){const dialog=document.querySelector('.aw-dialog'),items=[...(dialog?.querySelectorAll('button:not([disabled]),a[href],input,select,textarea,[tabindex="0"]')||[])];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;const meta=e.metaKey||e.ctrlKey,k=e.key.toLowerCase();if(meta&&k==='z'){e.preventDefault();e.shiftKey?w.redo():w.undo();}else if(meta&&k==='a'){e.preventDefault();selectedIds.value=project.value.nodes.filter(n=>!n.locked&&n.visible).map(n=>n.id);}else if(meta&&k==='d'){e.preventDefault();w.duplicate();}else if(meta&&k==='g'){e.preventDefault();e.shiftKey?w.ungroup():w.group();}else if(meta&&k==='c'){clipboard=JSON.parse(JSON.stringify(selected.value));w.notify('组件已复制');}else if(meta&&k==='v'&&clipboard){const groupMap=new Map();const nodes=clipboard.map(n=>{const c=structuredClone(n);c.id=crypto.randomUUID();c.x+=30;c.y+=30;if(c.group){if(!groupMap.has(c.group))groupMap.set(c.group,crypto.randomUUID());c.group=groupMap.get(c.group);}return c;});project.value.nodes.push(...nodes);selectedIds.value=nodes.map(n=>n.id);w.record();}else if(meta&&k==='s'){e.preventDefault();w.save();w.notify('设计已保存到本机');}else if(['Delete','Backspace'].includes(e.key)){e.preventDefault();w.remove();}else if(e.key.startsWith('Arrow')&&selected.value.length){e.preventDefault();const step=e.shiftKey?10:1;selected.value.filter(n=>!n.locked).forEach(n=>{if(e.key==='ArrowLeft')n.x-=step;if(e.key==='ArrowRight')n.x+=step;if(e.key==='ArrowUp')n.y-=step;if(e.key==='ArrowDown')n.y+=step;});w.record();}else if(k==='v'&&editor.value)editor.value.hand=false;else if(k==='h'&&editor.value)editor.value.hand=!editor.value.hand;else if(k==='?')modal.value='help';}
watch(modal,async value=>{document.body.style.overflow=value?'hidden':'';if(value){lastFocus=document.activeElement;await nextTick();document.querySelector('.aw-dialog button,.aw-dialog input,.aw-dialog a')?.focus();}else lastFocus?.focus?.();});
watch(ready,async value=>{if(!value)return;const params=new URLSearchParams(location.search),template=params.get('template');if(template&&templates.some(t=>t.id===template)){await w.applyTemplate(template);nav.value='templates';history.replaceState({},'',location.pathname+'?panel=templates');}});
onMounted(()=>{document.addEventListener('keydown',keydown);loadSession();});onBeforeUnmount(()=>{document.removeEventListener('keydown',keydown);document.body.style.overflow='';for(const url of libraryUrls.values())URL.revokeObjectURL(url);});
</script>
<template><div class="astra-workbench" :class="{'inspector-collapsed':!inspectorOpen}"><header class="aw-topbar"><a class="aw-brand" :href="sitePath('/')" aria-label="Astra Studio 首页"><span><Blocks :size="21" :stroke-width="1.6"/></span><strong>astra<span>studio</span></strong><i>2.0</i></a><div class="aw-workspace-breadcrumb"><span>我的工作空间</span><ChevronRight :size="12"/><strong>大屏设计器</strong></div><div class="aw-top-actions"><button class="aw-template-explore" @click="openNav('templates')"><LayoutTemplate :size="13"/>行业模板 <i>NEW</i></button><span class="aw-save-status"><i></i>{{saveStatus}}</span><button class="aw-secondary" @click="modal='preview'"><Eye :size="14"/>预览</button><button class="aw-primary" @click="modal='publish';shareUrl='';publishError=''"><Share2 :size="14"/>发布大屏</button><button class="aw-avatar" :title="session?.user?.name||'登录以同步云端项目'" @click="modal='publish'">{{session?.user?.name?.slice(0,1)||'A'}}</button></div></header>
 <div class="aw-workspace"><nav class="aw-rail" aria-label="工作区导航"><div><button v-for="item in navItems" :key="item.id" :class="{active:nav===item.id}" :aria-label="item.name" :aria-pressed="nav===item.id" @click="openNav(item.id)"><component :is="item.icon" :size="19" :stroke-width="1.6"/><span>{{item.name}}</span></button></div><div><a :href="sitePath('/header-studio/')" title="Header Studio"><PanelTop :size="18"/><span>Header</span></a><button aria-label="帮助与快捷键" @click="modal='help'"><HelpCircle :size="19"/><span>帮助</span></button></div></nav>
 <aside class="aw-library"><div class="aw-library-heading"><h2>{{navItems.find(i=>i.id===nav)?.name}}{{nav==='components'?'库':nav==='templates'?'市场':nav==='assets'?'库':''}}</h2><span>{{nav==='components'?libraryCount:nav==='layers'?objectCount:nav==='templates'?templates.length:nav==='assets'?libraryAssets.length:''}}</span><button v-if="nav==='assets'" title="上传素材" @click="fileInput.click()"><Plus :size="16"/></button><button v-if="nav==='projects'" title="新建项目" @click="w.applyTemplate('blank')"><Plus :size="16"/></button></div>
 <template v-if="nav==='components'"><p class="aw-library-subtitle">拖入画布，让想法即刻呈现。</p><div class="aw-search"><Search :size="14"/><input v-model="query" placeholder="搜索组件…" aria-label="搜索组件"/><span>⌕</span></div><div class="aw-component-categories"><button v-for="c in ['全部','基础','图表','空间','信息','装饰','媒体']" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="aw-component-list"><button v-for="item in filtered" :key="item.type" draggable="true" class="aw-component-card" :title="item.description" @dragstart="dragComponent($event,item)" @click="add(item.type)"><div><MiniPreview :type="item.type"/><span class="aw-card-add">+</span></div><strong>{{item.name}}</strong></button><div v-if="!filtered.length" class="aw-empty-state">没有找到这个组件<br/><button @click="query='';category='全部'">查看全部组件</button></div></div><div class="aw-library-footer"><i></i>原生 SVG · ECharts · Three.js</div></template>
 <template v-else-if="nav==='templates'"><p class="aw-library-subtitle">四种行业，四种视觉语言。预览后，自由创作。</p><div class="aw-template-list"><article v-for="t in templates" :key="t.id" class="aw-template-card"><button class="aw-template-thumb" :aria-label="'使用模板 '+t.name" :style="{'--template-accent':t.color}" @click="w.applyTemplate(t.id)"><TemplatePreview v-if="t.id!=='blank'" :template="t"/><Plus v-else :size="27" :stroke-width="1"/></button><div><strong>{{t.name}}</strong><span>{{t.tag}} <i v-if="['city','industry','agriculture','campus'].includes(t.id)">NEW</i></span><p>{{t.description}}</p><div class="aw-template-actions"><a v-if="['city','industry','agriculture','campus'].includes(t.id)" :href="sitePath('/templates/'+t.id+'/')" target="_blank" rel="noopener">全屏预览 <ArrowUpRight :size="10"/></a><button @click="w.applyTemplate(t.id)">使用模板 <Plus :size="10"/></button></div></div></article></div><div class="aw-library-footer">切换模板时，当前项目会自动保存。</div></template>
 <template v-else-if="nav==='layers'"><p class="aw-library-subtitle">上方组件位于更高图层。双击可单选。</p><div class="aw-layer-list"><div v-for="(n,i) in [...project.nodes].reverse()" :key="n.id" class="aw-layer-row" :class="{active:selectedIds.includes(n.id),hidden:!n.visible}"><button class="aw-layer-select" @click="w.select(n,$event.shiftKey)"><component :is="['scene','globe','model','map'].includes(n.type)?Box:chartTypes.includes(n.type)?Database:n.type==='header'?PanelTop:Shapes" :size="14"/><span><strong>{{n.name}}</strong><small>{{n.group?'组合 · ':''}}{{Math.round(n.w)}} × {{Math.round(n.h)}}</small></span></button><button :aria-label="(n.locked?'解锁':'锁定')+n.name" @click="toggleLock(n)"><component :is="n.locked?Lock:Unlock" :size="12"/></button><button :aria-label="(n.visible?'隐藏':'显示')+n.name" @click="toggleVisible(n)"><component :is="n.visible?Eye:EyeOff" :size="13"/></button></div><div v-if="!project.nodes.length" class="aw-empty-state">画布还是空的<br/>从组件库添加第一个组件吧。</div></div><div class="aw-library-footer">Shift 点击多选 · ⌘G 组合</div></template>
 <template v-else-if="nav==='assets'"><p class="aw-library-subtitle">把你的品牌、场景和想象带进来。</p><button class="aw-upload-zone" :disabled="busy" @click="fileInput.click()"><Upload :size="22" :stroke-width="1.4"/><strong>{{busy?'正在处理素材…':'上传自定义素材'}}</strong><span>图片 / 视频 / SVG / GLB / glTF</span><small>单个文件最大 50 MB · 本机保存</small></button><div class="aw-asset-list"><article v-for="asset in libraryAssets" :key="asset.id"><button class="aw-asset-thumb" :aria-label="'添加素材 '+asset.name" @click="w.useAsset(asset)"><img v-if="['image','svg'].includes(asset.type)" :src="assetUrl(asset)" :alt="asset.name" loading="lazy"/><component v-else :is="asset.type==='model'?Box:Video" :size="28" :stroke-width="1"/><i>+</i></button><div><strong :title="asset.name">{{asset.name}}</strong><span>{{asset.type.toUpperCase()}} · {{(asset.size/1024/1024).toFixed(1)}} MB</span><button :aria-label="'删除素材 '+asset.name" @click="w.deleteAsset(asset)"><Trash2 :size="11"/></button></div><button class="aw-asset-bg" v-if="['image','svg'].includes(asset.type)" @click="project.background.assetId=asset.id;if(!project.assets.some(a=>a.id===asset.id)){const {blob,...meta}=asset;project.assets.push(meta);}w.setProject(w.raw());w.record()">设为画布背景</button></article><button class="aw-model-sample" @click="add('model')"><Box :size="21"/><div><strong>工业设备示例模型</strong><span>内置 GLB · 可拾取 · 带动画</span></div><Plus :size="14"/></button></div></template>
 <template v-else-if="nav==='projects'"><p class="aw-library-subtitle">你的创作，始终在这里。</p><button class="aw-new-project" @click="w.applyTemplate('blank')"><Plus :size="15"/>新建空白大屏</button><div class="aw-project-list"><button v-for="p in projects" :key="p.id" :class="{active:p.id===project.id}" @click="w.setProject(p)"><span><Monitor :size="19"/></span><div><strong>{{p.name}}</strong><small>{{p.width}} × {{p.height}} · {{p.nodes.length}} 个组件</small><time>{{new Date(p.updatedAt).toLocaleDateString('zh-CN')}}</time></div><Check v-if="p.id===project.id" :size="13"/></button></div><div v-if="cloudProjects.some(p=>!projects.some(local=>local.id===p.id))" class="aw-cloud-project-list"><h3>云端项目</h3><button v-for="p in cloudProjects.filter(p=>!projects.some(local=>local.id===p.id))" :key="p.id" @click="openCloudProject(p.id)"><Cloud :size="15"/><span>{{p.name}}</span><ArrowUpRight :size="11"/></button></div><div class="aw-project-import"><button class="aw-secondary wide" @click="jsonInput.click()"><Upload :size="13"/>导入项目配置</button><p>本机草稿保存在当前浏览器。发布后获得跨设备分享链接。</p></div></template>
 <template v-else-if="nav==='history'"><p class="aw-library-subtitle">每一次尝试，都有回到原点的自由。</p><div class="aw-history-actions"><button class="aw-primary wide" @click="localSnapshot"><Plus :size="13"/>保存设计快照</button><button class="aw-secondary wide" :disabled="busy" @click="cloudSnapshot"><CloudUpload :size="13"/>保存云端版本</button></div><div class="aw-version-list"><div v-for="s in [...snapshots,...cloudVersions]" :key="s.id"><span class="aw-version-dot"></span><div><strong>{{s.name}}</strong><small>{{s.project?'本机快照':'云端版本'}} · {{new Date(s.createdAt||s.created_at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}}</small><button @click="s.project?w.restoreSnapshot(s):restoreCloud(s)">恢复此版本 <History :size="11"/></button></div></div><div v-if="!snapshots.length&&!cloudVersions.length" class="aw-empty-state">还没有历史快照<br/>在重要修改前，保存一个版本。</div></div><div class="aw-library-footer">恢复后仍可撤销。发布会自动保存云端版本。</div></template>
 </aside>
 <main class="aw-main"><div class="aw-document-bar"><div><FolderOpen :size="15"/><input v-model="project.name" aria-label="大屏名称" maxlength="80" @change="w.record()"/><span class="aw-document-tag">大屏</span><ChevronDown :size="12"/></div><div><button aria-label="撤销" title="撤销 ⌘Z" :disabled="!canUndo" @click="w.undo"><Undo2 :size="15"/></button><button aria-label="重做" title="重做 ⌘⇧Z" :disabled="!canRedo" @click="w.redo"><Redo2 :size="15"/></button><i></i><div class="aw-more-wrap"><button @click="showMore=!showMore" aria-label="导入导出菜单"><MoreHorizontal :size="18"/></button><div v-if="showMore" class="aw-popup-menu"><button @click="jsonInput.click();showMore=false"><Upload :size="13"/>导入项目配置</button><button @click="exportConfig"><FileJson :size="13"/>导出 JSON 配置</button><button :disabled="busy" @click="exportPackage"><Download :size="13"/>打包项目与素材</button><a :href="sitePath('/city/')" target="_blank"><ExternalLink :size="13"/>查看原智慧城市大屏</a></div></div></div></div>
 <div class="aw-edit-toolbar" role="toolbar" aria-label="画布编辑工具"><div><button :class="{active:!editor?.hand}" aria-label="选择工具" title="选择 V" @click="editor.hand=false"><MousePointer2 :size="16"/></button><button :class="{active:editor?.hand}" aria-label="平移工具" title="平移 H / Space" @click="editor.hand=!editor.hand"><Hand :size="16"/></button><i></i><button :class="{active:project.grid}" :aria-pressed="project.grid" aria-label="显示智能网格" @click="project.grid=!project.grid;w.record()"><Grid2X2 :size="16"/></button><button :class="{active:project.snap}" :aria-pressed="project.snap" aria-label="自动吸附对齐" @click="project.snap=!project.snap;w.record()"><Magnet :size="16"/></button><i></i><div class="aw-align-wrap"><button :disabled="!selected.length" aria-label="对齐与排列" @click="showAlign=!showAlign"><AlignLeft :size="16"/><ChevronDown :size="10"/></button><div v-if="showAlign" class="aw-popup-menu align-menu"><span>对齐组件</span><div><button v-for="[mode,name,icon] in [['left','左对齐',AlignLeft],['center','水平居中',AlignCenter],['right','右对齐',AlignRight],['top','顶部对齐',AlignStartVertical],['middle','垂直居中',AlignVerticalJustifyCenter],['bottom','底部对齐',AlignEndVertical]]" :key="mode" :aria-label="name" :title="name" @click="w.align(mode)"><component :is="icon" :size="16"/></button></div><button @click="w.distribute('x')"><MoveHorizontal :size="14"/>水平等间距</button><button @click="w.distribute('y')"><MoveVertical :size="14"/>垂直等间距</button></div></div><button :disabled="selected.length<2" title="组合 ⌘G" aria-label="组合所选组件" @click="w.group"><Group :size="16"/></button><button :disabled="!selected.some(n=>n.group)" title="取消组合 ⌘⇧G" aria-label="取消组合" @click="w.ungroup"><Ungroup :size="16"/></button><i></i><button :disabled="!selected.length" title="置顶" aria-label="置顶" @click="w.reorder('front')"><ArrowUpToLine :size="15"/></button><button :disabled="!selected.length" title="置底" aria-label="置底" @click="w.reorder('back')"><ArrowDownToLine :size="15"/></button><button :disabled="!selected.length" title="复制 ⌘D" aria-label="复制组件" @click="w.duplicate"><Copy :size="15"/></button><button :disabled="!selected.length" title="删除 Delete" aria-label="删除组件" @click="w.remove"><Trash2 :size="15"/></button></div><div><span>{{selected.length?selected.length+' 个已选':objectCount+' 个组件'}}</span><button :aria-label="playing?'暂停动效':'播放动效'" @click="playing=!playing"><component :is="playing?Pause:Play" :size="14"/></button><button aria-label="切换配置面板" @click="inspectorOpen=!inspectorOpen"><Settings2 :size="16"/></button></div></div>
 <CanvasEditor v-if="ready" ref="editor" :project="project" :selected-ids="selectedIds" :playing="playing&&!modal" :assets="assetUrls" @select="w.select" @selection="selectedIds=$event" @record="w.record" @add="add"/><div v-else class="aw-workbench-loading"><LoaderCircle :size="24" class="spin"/>正在恢复你的工作空间</div>
 <footer class="aw-statusbar"><span><i></i>编辑模式 <b>本地演示数据</b></span><span>WebGL / SVG / ECharts <button @click="modal='help'"><Keyboard :size="12"/>快捷键</button></span></footer></main>
 <PropertyPanel v-if="inspectorOpen" :project="project" :node="selection" :count="selected.length" @record="w.record" @notify="w.notify" @assets="openNav('assets')" @close="inspectorOpen=false"/>
 </div><input ref="fileInput" type="file" multiple accept=".glb,.gltf,.svg,.png,.jpg,.jpeg,.webp,.gif,.mp4,.webm" hidden @change="files"/><input ref="jsonInput" type="file" accept=".json,.zip" hidden @change="importConfig"/>
 <Transition name="aw-toast"><div v-if="toast" class="aw-toast-message" role="status"><CheckCheck :size="16"/>{{toast}}</div></Transition>
 <div v-if="modal==='preview'" class="aw-modal-backdrop preview-backdrop" @click.self="modal=null"><section class="aw-dialog aw-preview-dialog" role="dialog" aria-modal="true" aria-label="大屏实时预览"><header><div><span class="aw-live-dot"></span><strong>{{project.name}}</strong><span>实时预览 · 点击组件体验交互联动</span></div><div><select v-model="project.fit" aria-label="预览适配方式"><option value="contain">等比适应</option><option value="cover">全屏铺满</option><option value="width">宽度适应</option><option value="stretch">拉伸填满</option></select><button aria-label="预览全屏" @click="$event.currentTarget.closest('section').requestFullscreen?.()"><Maximize2 :size="16"/></button><button aria-label="关闭预览" @click="modal=null"><X :size="19"/></button></div></header><ScreenPlayer :project="project" :playing="playing" :assets="assetUrls"/><footer><span>真实场景交互 · 配置即所见</span><button @click="playing=!playing"><component :is="playing?Pause:Play" :size="14"/>{{playing?'暂停动效':'播放动效'}}</button></footer></section></div>
 <div v-if="modal==='publish'" class="aw-modal-backdrop" @click.self="!busy&&(modal=null)"><section class="aw-dialog aw-publish-dialog" role="dialog" aria-modal="true" aria-label="发布大屏"><header><div><Share2 :size="17"/><strong>让你的设计，被看见。</strong></div><button aria-label="关闭发布" :disabled="busy" @click="modal=null"><X :size="18"/></button></header><div class="aw-publish-body"><div class="aw-publish-summary"><span><Monitor :size="24" :stroke-width="1.3"/></span><div><strong>{{project.name}}</strong><small>{{project.width}} × {{project.height}} · {{objectCount}} 个组件</small></div><i>READY</i></div><template v-if="!shareUrl"><p class="aw-publish-label">选择访问方式</p><div class="aw-access-modes"><button v-for="m in [{id:'public',name:'公开分享',icon:Globe2,description:'持有链接即可查看'},{id:'password',name:'密码查看',icon:Lock,description:'输入正确密码后查看'},{id:'token',name:'Token 验证',icon:ShieldCheck,description:'使用独立访问令牌'}]" :class="{active:publishMode===m.id}" @click="publishMode=m.id"><component :is="m.icon" :size="18"/><strong>{{m.name}}</strong><span>{{m.description}}</span><Check v-if="publishMode===m.id" :size="13"/></button></div><label v-if="publishMode==='password'" class="aw-publish-password">查看密码<input v-model="password" type="password" minlength="6" autocomplete="new-password" placeholder="设置至少 6 位密码" aria-label="大屏查看密码"/></label><div class="aw-publish-note"><History :size="15"/><p>发布时自动保存云端快照，可在历史中恢复。上传素材会同步到你的账号。</p></div><div v-if="!cloudReady" class="aw-signin-note"><LogIn :size="16"/><div><strong>{{isStaticHosting?'当前为 GitHub Pages 本机模式':'登录后发布并同步到云端'}}</strong><p>{{isStaticHosting?'可编辑、预览和导出项目；云端保存、SQL 与受保护分享需要部署 Worker 后端。':'编辑与本机保存无需登录。'}}</p><a v-if="!isStaticHosting" :href="session?.signInUrl||'/signin-with-chatgpt?return_to=%2F'" target="_top">使用 ChatGPT 登录 <ArrowUpRight :size="13"/></a></div></div><p v-if="publishError" class="aw-form-error">{{publishError}}</p><button class="aw-primary wide publish-action" :disabled="busy||!cloudReady" @click="publish"><component :is="busy?LoaderCircle:Share2" :class="{spin:busy}" :size="15"/>{{busy?'正在同步素材并发布…':'发布这个大屏'}}</button></template><template v-else><div class="aw-publish-success"><CheckCircle2 :size="30" :stroke-width="1.3"/><h3>已经准备好，与你的观众见面。</h3><p>大屏已发布，访问权限已在服务端生效。</p></div><label class="aw-share-link"><input :value="shareUrl" aria-label="大屏分享链接" readonly/><button @click="copyShare"><Copy :size="15"/></button></label><p v-if="publishMode==='token'" class="aw-field-note">该链接含访问令牌，请仅分享给需要查看的人。重新发布将更新令牌。</p><a :href="shareUrl" class="aw-primary wide" target="_blank" rel="noopener">打开已发布大屏 <ArrowUpRight :size="14"/></a></template></div></section></div>
 <div v-if="modal==='help'" class="aw-modal-backdrop" @click.self="modal=null"><section class="aw-dialog aw-help-dialog" role="dialog" aria-modal="true" aria-label="快速上手"><header><div><Keyboard :size="18"/><strong>让灵感，少一些等待。</strong></div><button aria-label="关闭帮助" @click="modal=null"><X :size="18"/></button></header><div><p>拖入组件 → 配置样式与数据 → 实时预览 → 发布分享</p><dl><template v-for="[name,key] in [['选择 / 平移','V / H'],['临时平移画布','Space + 拖动'],['多选组件','Shift + 点击 / 框选'],['单独选择组合内组件','双击'],['撤销 / 重做','⌘ Z / ⌘ ⇧ Z'],['复制组件','⌘ D'],['复制 / 粘贴','⌘ C / ⌘ V'],['组合 / 解组','⌘ G / ⌘ ⇧ G'],['精细移动 / 快速移动','方向键 / Shift + 方向键'],['等比缩放 / 关闭吸附','Shift / Alt + 拖动'],['画布缩放','⌘ + 滚轮'],['保存 / 删除','⌘ S / Delete']]"><dt>{{name}}</dt><dd>{{key}}</dd></template></dl><p>Windows / Linux 使用 Ctrl 替代 ⌘。所有演示数据均可替换为真实数据源。</p><div class="aw-help-links"><a :href="sitePath('/header-studio/')" target="_blank">Header Studio <ArrowUpRight :size="12"/></a><a :href="sitePath('/city/')" target="_blank">城市大屏 <ArrowUpRight :size="12"/></a><a :href="sitePath('/demo01/')" target="_blank">农业 <ArrowUpRight :size="12"/></a><a :href="sitePath('/demo02/')" target="_blank">工业 <ArrowUpRight :size="12"/></a><a :href="sitePath('/demo03/')" target="_blank">园区 <ArrowUpRight :size="12"/></a></div></div></section></div>
 </div></template>
